1	package com.example.starter.incident;
2	
3	import java.sql.ResultSet;
4	import java.sql.SQLException;
5	import java.sql.Statement;
6	import java.sql.Timestamp;
7	import java.time.Instant;
8	import java.util.ArrayDeque;
9	import java.util.ArrayList;
10	import java.util.Deque;
11	import java.util.HashMap;
12	import java.util.HashSet;
13	import java.util.List;
14	import java.util.Map;
15	import java.util.Optional;
16	import java.util.Set;
17	
18	import org.springframework.dao.DuplicateKeyException;
19	import org.springframework.jdbc.core.JdbcTemplate;
20	import org.springframework.jdbc.core.RowMapper;
21	import org.springframework.jdbc.support.GeneratedKeyHolder;
22	import org.springframework.jdbc.support.KeyHolder;
23	import org.springframework.stereotype.Repository;
24	
25	/**
26	 * 处置任务及跨事件阻塞关系的 JDBC 仓储。
27	 * 所有写路径均处于先锁定事件行的写事务内；创建任务额外持有 task_graph_lock 单行锁，
28	 * 使环检测与边写入相对其他创建串行化，保证并发反向依赖下最终图无环。
29	 */
30	@Repository
31	public class IncidentTaskRepository {
32	
33	    /** 依赖图全局锁行的固定主键。 */
34	    private static final long GRAPH_LOCK_ID = 1L;
35	
36	    private final JdbcTemplate jdbc;
37	
38	    public IncidentTaskRepository(JdbcTemplate jdbc) {
39	        this.jdbc = jdbc;
40	    }
41	
42	    private static final RowMapper<IncidentTask> TASK_MAPPER = (rs, n) -> mapTask(rs);
43	
44	    private static IncidentTask mapTask(ResultSet rs) throws SQLException {
45	        Timestamp doneAt = rs.getTimestamp("done_at");
46	        Timestamp cancelledAt = rs.getTimestamp("cancelled_at");
47	        return new IncidentTask(
48	                rs.getLong("id"), rs.getLong("incident_id"), rs.getString("task_key"),
49	                rs.getString("group_code"), rs.getString("title"),
50	                TaskStatus.valueOf(rs.getString("status")),
51	                rs.getString("created_by"), rs.getString("done_by"),
52	                doneAt == null ? null : doneAt.toInstant(),
53	                rs.getString("cancelled_by"),
54	                cancelledAt == null ? null : cancelledAt.toInstant(),
55	                rs.getTimestamp("created_at").toInstant(),
56	                rs.getTimestamp("updated_at").toInstant());
57	    }
58	
59	    /**
60	     * 依赖图有向边：fromIncidentId（任务所属事件）→ toIncidentId（阻塞事件）。
61	     */
62	    public record Edge(long fromIncidentId, long toIncidentId) {
63	    }
64	
65	    /**
66	     * 插入 OPEN 任务，返回生成主键。(incident_id, task_key) 唯一约束兜底并发重复插入。
67	     */
68	    public long insert(IncidentTask task) {
69	        KeyHolder keys = new GeneratedKeyHolder();
70	        jdbc.update(con -> {
71	            var ps = con.prepareStatement(
72	                    "INSERT INTO incident_tasks (incident_id, task_key, group_code, title, status,"
73	                            + " created_by, done_by, done_at, cancelled_by, cancelled_at,"
74	                            + " created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",
75	                    Statement.RETURN_GENERATED_KEYS);
76	            ps.setLong(1, task.incidentId());
77	            ps.setString(2, task.taskKey());
78	            ps.setString(3, task.groupCode());
79	            ps.setString(4, task.title());
80	            ps.setString(5, task.status().name());
81	            ps.setString(6, task.createdBy());
82	            ps.setString(7, task.doneBy());
83	            ps.setTimestamp(8, task.doneAt() == null ? null : Timestamp.from(task.doneAt()));
84	            ps.setString(9, task.cancelledBy());
85	            ps.setTimestamp(10, task.cancelledAt() == null ? null : Timestamp.from(task.cancelledAt()));
86	            ps.setTimestamp(11, Timestamp.from(task.createdAt()));
87	            ps.setTimestamp(12, Timestamp.from(task.updatedAt()));
88	            return ps;
89	        }, keys);
90	        return keys.getKey().longValue();
91	    }
92	
93	    /**
94	     * 按事件与 taskKey 查询任务，用于幂等比对与明细查询。
95	     */
96	    public Optional<IncidentTask> findByKey(long incidentId, String taskKey) {
97	        List<IncidentTask> rows = jdbc.query(
98	                "SELECT * FROM incident_tasks WHERE incident_id = ? AND task_key = ?",
99	                TASK_MAPPER, incidentId, taskKey);
100	        return rows.stream().findFirst();
101	    }
102	
103	    /**
104	     * 查询事件全部任务，按创建顺序返回。
105	     */
106	    public List<IncidentTask> listByIncident(long incidentId) {
107	        return jdbc.query("SELECT * FROM incident_tasks WHERE incident_id = ? ORDER BY id",
108	                TASK_MAPPER, incidentId);
109	    }
110	
111	    /**
112	     * 查询事件仍 OPEN 的任务（解决门禁用），按创建顺序返回。
113	     */
114	    public List<IncidentTask> listOpenByIncident(long incidentId) {
115	        return jdbc.query("SELECT * FROM incident_tasks WHERE incident_id = ? AND status = 'OPEN'"
116	                + " ORDER BY id", TASK_MAPPER, incidentId);
117	    }
118	
119	    /**
120	     * 统计事件任务数（每事件至多 20 个）。
121	     */
122	    public int countByIncident(long incidentId) {
123	        Integer count = jdbc.queryForObject(
124	                "SELECT COUNT(*) FROM incident_tasks WHERE incident_id = ?", Integer.class, incidentId);
125	        return count == null ? 0 : count;
126	    }
127	
128	    /**
129	     * 将 OPEN 任务置为 DONE，记录完成人与 UTC 时刻。
130	     */
131	    public void markDone(long id, String actor, Instant at) {
132	        jdbc.update("UPDATE incident_tasks SET status = 'DONE', done_by = ?, done_at = ?,"
133	                        + " updated_at = ? WHERE id = ?",
134	                actor, Timestamp.from(at), Timestamp.from(at), id);
135	    }
136	
137	    /**
138	     * 将 OPEN 任务置为 CANCELLED，记录取消人与 UTC 时刻。
139	     */
140	    public void markCancelled(long id, String actor, Instant at) {
141	        jdbc.update("UPDATE incident_tasks SET status = 'CANCELLED', cancelled_by = ?,"
142	                        + " cancelled_at = ?, updated_at = ? WHERE id = ?",
143	                actor, Timestamp.from(at), Timestamp.from(at), id);
144	    }
145	
146	    /**
147	     * 追加一条阻塞边（任务 → 阻塞事件）。(task_id, blocker_incident_id) 唯一。
148	     */
149	    public void insertBlocker(long taskId, long blockerIncidentId, Instant now) {
150	        jdbc.update("INSERT INTO incident_task_blockers (task_id, blocker_incident_id, created_at)"
151	                + " VALUES (?,?,?)", taskId, blockerIncidentId, Timestamp.from(now));
152	    }
153	
154	    /**
155	     * 持有依赖图全局锁（单行 SELECT ... FOR UPDATE），串行化环检测与边写入。
156	     * 锁行不存在时先插入；并发首次插入由主键约束串行化。
157	     */
158	    public void lockGraph() {
159	        try {
160	            jdbc.update("INSERT INTO task_graph_lock (id) VALUES (?)", GRAPH_LOCK_ID);
161	        } catch (DuplicateKeyException e) {
162	            // 锁行已存在（含并发事务已提交），继续加锁
163	        }
164	        jdbc.queryForObject("SELECT id FROM task_graph_lock WHERE id = ? FOR UPDATE",
165	                Long.class, GRAPH_LOCK_ID);
166	    }
167	
168	    /**
169	     * 环检测：在依赖图中判断从 fromIncidentId 出发沿阻塞边是否可达 toIncidentId。
170	     * 调用前必须已持有 lockGraph() 全局锁，保证检测与后续边写入串行一致。
171	     * 所有状态的任务边均参与构图（保守策略：已终态任务的依赖边仍阻止成环）。
172	     */
173	    public boolean isReachable(long fromIncidentId, long toIncidentId) {
174	        if (fromIncidentId == toIncidentId) {
175	            return true;
176	        }
177	        List<Edge> edges = jdbc.query(
178	                "SELECT t.incident_id, b.blocker_incident_id FROM incident_task_blockers b"
179	                        + " JOIN incident_tasks t ON t.id = b.task_id",
180	                (rs, n) -> new Edge(rs.getLong(1), rs.getLong(2)));
181	        Map<Long, List<Long>> adjacency = new HashMap<>();
182	        for (Edge edge : edges) {
183	            adjacency.computeIfAbsent(edge.fromIncidentId(), k -> new ArrayList<>())
184	                    .add(edge.toIncidentId());
185	        }
186	        Set<Long> visited = new HashSet<>();
187	        Deque<Long> queue = new ArrayDeque<>();
188	        queue.add(fromIncidentId);
189	        visited.add(fromIncidentId);
190	        while (!queue.isEmpty()) {
191	            long current = queue.poll();
192	            for (Long next : adjacency.getOrDefault(current, List.of())) {
193	                if (next == toIncidentId) {
194	                    return true;
195	                }
196	                if (visited.add(next)) {
197	                    queue.add(next);
198	                }
199	            }
200	        }
201	        return false;
202	    }
203	}
