41	        jdbc.update("DELETE FROM incidents");
42	    }
43	
44	    private static String key() {
45	        return "CMD-" + UUID.randomUUID();
46	    }
47	
48	    private void report(String incidentKey) throws Exception {
49	        mvc.perform(post("/api/incidents")
50	                        .contentType(MediaType.APPLICATION_JSON)
51	                        .content("{\"incidentKey\":\"" + incidentKey
52	                                + "\",\"severity\":\"S1\",\"summary\":\"s\",\"reporter\":\"r\"}"))
53	                .andExpect(status().isCreated());
54	    }
55	
56	    private void takeover(String incidentKey, String actor) throws Exception {
57	        mvc.perform(post("/api/incidents/{k}/takeover", incidentKey)
58	                        .header("X-Actor-Id", actor)
59	                        .contentType(MediaType.APPLICATION_JSON)
60	                        .content("{\"commandKey\":\"" + key() + "\"}"))
61	                .andExpect(status().isOk());
62	    }
63	
64	    private void createTask(String incidentKey, String actor, String taskKey,
65	                            String blockersJson) throws Exception {
66	        mvc.perform(post("/api/incidents/{k}/tasks", incidentKey)
67	                        .header("X-Actor-Id", actor)
68	                        .contentType(MediaType.APPLICATION_JSON)
69	                        .content("{\"commandKey\":\"" + key() + "\",\"taskKey\":\"" + taskKey
70	                                + "\",\"groupCode\":\"DB\",\"title\":\"扩容\","
71	                                + "\"blockerIncidentKeys\":" + blockersJson + "}"))
72	                .andExpect(status().isOk())
73	                .andExpect(jsonPath("$.taskKey").value(taskKey))
74	                .andExpect(jsonPath("$.status").value("OPEN"));
75	    }
76	
77	    private void changeStatus(String incidentKey, String actor, String target) throws Exception {
78	        mvc.perform(post("/api/incidents/{k}/status", incidentKey)
79	                        .header("X-Actor-Id", actor)
80	                        .contentType(MediaType.APPLICATION_JSON)
81	                        .content("{\"commandKey\":\"" + key() + "\",\"targetStatus\":\""
82	                                + target + "\"}"))
83	                .andExpect(status().isOk());
84	    }
