86	    @Test
87	    void taskHttpFlow() throws Exception {
88	        report("INC-500");
89	        report("INC-501");
90	        takeover("INC-500", "alice");
91	        takeover("INC-501", "bob");
92	
93	        // 创建任务（带阻塞事件）
94	        createTask("INC-500", "alice", "T-1", "[\"INC-501\"]");
95	
96	        // 按事件分组查询
97	        mvc.perform(get("/api/incidents/{k}/tasks", "INC-500"))
98	                .andExpect(status().isOk())
99	                .andExpect(jsonPath("$.incidentKey").value("INC-500"))
100	                .andExpect(jsonPath("$.tasks.length()").value(1))
101	                .andExpect(jsonPath("$.tasks[0].blockers[0].incidentKey").value("INC-501"))
102	                .andExpect(jsonPath("$.tasks[0].blockers[0].resolved").value(false));
103	
104	        // 单任务明细
105	        mvc.perform(get("/api/incidents/{k}/tasks/{t}", "INC-500", "T-1"))
106	                .andExpect(status().isOk())
107	                .andExpect(jsonPath("$.groupCode").value("DB"))
108	                .andExpect(jsonPath("$.createdBy").value("alice"));
109	
110	        // 阻塞未解除时完成 → 409 且 details 返回未解除事件列表
111	        mvc.perform(post("/api/incidents/{k}/tasks/{t}/complete", "INC-500", "T-1")
112	                        .header("X-Actor-Id", "alice")
113	                        .contentType(MediaType.APPLICATION_JSON)
114	                        .content("{\"commandKey\":\"" + key() + "\"}"))
115	                .andExpect(status().isConflict())
116	                .andExpect(jsonPath("$.code").value("CONFLICT"))
117	                .andExpect(jsonPath("$.details[0]").value("INC-501"));
118	
119	        // 阻塞事件遏制后完成成功
120	        changeStatus("INC-501", "bob", "CONTAINED");
121	        mvc.perform(post("/api/incidents/{k}/tasks/{t}/complete", "INC-500", "T-1")
122	                        .header("X-Actor-Id", "alice")
123	                        .contentType(MediaType.APPLICATION_JSON)
