183	        report("INC-520");
184	        report("INC-521");
185	        takeover("INC-520", "alice");
186	        takeover("INC-521", "bob");
187	        createTask("INC-520", "alice", "T-1", "[\"INC-521\"]");
188	
189	        // 反向依赖成环 → 409
190	        mvc.perform(post("/api/incidents/{k}/tasks", "INC-521")
191	                        .header("X-Actor-Id", "bob")
192	                        .contentType(MediaType.APPLICATION_JSON)
193	                        .content("{\"commandKey\":\"" + key() + "\",\"taskKey\":\"T-1\","
194	                                + "\"groupCode\":\"G\",\"title\":\"t\","
195	                                + "\"blockerIncidentKeys\":[\"INC-520\"]}"))
196	                .andExpect(status().isConflict())
197	                .andExpect(jsonPath("$.code").value("CONFLICT"));
198	
199	        // 仍有 OPEN 任务时推进 RESOLVED → 409 且 details 按 groupCode、taskKey 返回
200	        changeStatus("INC-520", "alice", "CONTAINED");
201	        mvc.perform(post("/api/incidents/{k}/status", "INC-520")
202	                        .header("X-Actor-Id", "alice")
203	                        .contentType(MediaType.APPLICATION_JSON)
204	                        .content("{\"commandKey\":\"" + key()
205	                                + "\",\"targetStatus\":\"RESOLVED\"}"))
206	                .andExpect(status().isConflict())
207	                .andExpect(jsonPath("$.details[0].groupCode").value("DB"))
208	                .andExpect(jsonPath("$.details[0].taskKey").value("T-1"));
209	
210	        // 取消任务后解决成功
211	        mvc.perform(post("/api/incidents/{k}/tasks/{t}/cancel", "INC-520", "T-1")
212	                        .header("X-Actor-Id", "alice")
213	                        .contentType(MediaType.APPLICATION_JSON)
214	                        .content("{\"commandKey\":\"" + key() + "\"}"))
215	                .andExpect(status().isOk());
216	        changeStatus("INC-520", "alice", "RESOLVED");
217	    }
218	}
